{
  "qa": [
    {
      "question": "针对店内巡逻中发现的摇头丸或笑气等违禁物品使用行为，应如何及时处理？",
      "answer": "发现使用摇头丸或笑气等违禁物品的行为应立即报警，并先将涉嫌售卖毒品人员控制起来再进行后续处理。"
    },
    {
      "question": "为防止顾客携带毒品进入场所，是否需要在入口处设置物品暂存区？",
      "answer": "为防止顾客携带毒品进入场所，可在入口处设置物品暂存区，要求顾客将背包、外套等非必要物品存放，仅允许携带手机和贵重物品进入。"
    },
    {
      "question": "针对顾客可能携带的毒品，如何在入场环节实施有效管控？",
      "answer": "入场环节应通过设置储物柜限制背包、外套等物品携带，同时结合安检设备扫描，形成多层管控措施以减少毒品进入风险。"
    }
  ]
}
